namespace GUI {
    void drawFrogLogo(Arduino_GFX &gfx, int16_t x, int16_t y)
    {
        for (int16_t row = 0; row < FROG_ORIG_HEIGHT; ++row) {
            for (int16_t column = 0; column < FROG_ORIG_WIDTH; ++column) {
                const uint16_t color =
                    pgm_read_word(&frog_logo_bits[
                        (row + FROG_CROP_Y) * FROG_SOURCE_WIDTH + column + FROG_CROP_X]);
                gfx.fillRect(x + column * 2, y + row * 2, 2, 2, color);
            }
        }
    }
}
